{"file_path":"src/cli.js","content":"#!/usr/bin/env node

const fs = require('fs');

// Parse command line
const mode = process.argv[2];
if (!['merge', 'merge2', 'regions'].includes(mode)) {
  process.stderr.write('error: usage: cli.js merge|merge2|regions\n');
  process.exit(2);
}

// Read all input from stdin synchronously
let input = '';
try {
  input = fs.readFileSync(0, 'utf-8');
} catch (e) {
  // If reading from stdin fails, try empty input
  input = '';
}

// Parse documents
const parts = input.split('%%%\n');
if (parts.length !== 3) {
  process.stderr.write('error: expected three parts separated by %%%\n');
  process.exit(2);
}

// Parse each part into lines, removing trailing empty line if present
function parseDocument(part) {
  let lines = part.split('\n');
  // Remove trailing empty string from final newline
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop();
  }
  return lines;
}

const mine = parseDocument(parts[0]);
const base = parseDocument(parts[1]);
const theirs = parseDocument(parts[2]);

// Greedy LCS algorithm that matches when possible
function greedyLCS(doc1, doc2) {
  let i = 0, j = 0;
  const indices1 = [];
  const indices2 = [];

  while (i < doc1.length && j < doc2.length) {
    if (doc1[i] === doc2[j]) {
      indices1.push(i);
      indices2.push(j);
      i++;
      j++;
    } else {
      const remaining1 = doc1.length - i;
      const remaining2 = doc2.length - j;
      if (remaining2 >= remaining1) {
        j++;
      } else {
        i++;
      }
    }
  }

  return { indices1, indices2 };
}

// Extract changes from LCS
function extractChanges(doc, base, lcsIndices) {
  const changes = [];
  let lastBaseIdx = -1;
  let lastDocIdx = -1;

  for (let k = 0; k < lcsIndices.base.length; k++) {
    const baseIdx = lcsIndices.base[k];
    const docIdx = lcsIndices.doc[k];

    const baseGap = baseIdx - lastBaseIdx - 1;
    const docGap = docIdx - lastDocIdx - 1;

    if (baseGap > 0 || docGap > 0) {
      changes.push({
        baseStart: lastBaseIdx + 1,
        baseEnd: baseIdx,
        docStart: lastDocIdx + 1,
        docEnd: docIdx,
      });
    }

    lastBaseIdx = baseIdx;
    lastDocIdx = docIdx;
  }

  // Handle trailing changes
  const baseGap = base.length - lastBaseIdx - 1;
  const docGap = doc.length - lastDocIdx - 1;
  if (baseGap > 0 || docGap > 0) {
    changes.push({
      baseStart: lastBaseIdx + 1,
      baseEnd: base.length,
      docStart: lastDocIdx + 1,
      docEnd: doc.length,
    });
  }

  return changes;
}

// Compute LCS for both sides
const mineResult = greedyLCS(mine, base);
const theirsResult = greedyLCS(theirs, base);

// Extract changes
const mineChanges = extractChanges(mine, base, { doc: mineResult.indices1, base: mineResult.indices2 });
const theirsChanges = extractChanges(theirs, base, { doc: theirsResult.indices1, base: theirsResult.indices2 });

// Merge changes into regions
const allChanges = [];
mineChanges.forEach(c => allChanges.push({ ...c, side: 'mine' }));
theirsChanges.forEach(c => allChanges.push({ ...c, side: 'theirs' }));

// Sort by baseStart, then by side (mine before theirs)
allChanges.sort((a, b) => {
  if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart;
  return a.side === 'mine' ? -1 : 1;
});

// Merge overlapping changes into regions
const regions = [];
let currentRegion = null;

for (const change of allChanges) {
  if (currentRegion === null) {
    currentRegion = {
      baseStart: change.baseStart,
      baseEnd: change.baseEnd,
      changes: [change],
    };
  } else if (change.baseStart <= currentRegion.baseEnd) {
    currentRegion.baseEnd = Math.max(currentRegion.baseEnd, change.baseEnd);
    currentRegion.changes.push(change);
  } else {
    regions.push(currentRegion);
    currentRegion = {
      baseStart: change.baseStart,
      baseEnd: change.baseEnd,
      changes: [change],
    };
  }
}
if (currentRegion !== null) {
  regions.push(currentRegion);
}

// Process regions and generate output
const output = [];
let hasConflict = false;

let basePos = 0;
for (const region of regions) {
  // Add stable region before this region
  if (basePos < region.baseStart) {
    const stableLines = base.slice(basePos, region.baseStart);
    if (mode === 'regions') {
      if (stableLines.length > 0) {
        output.push(`stable ${stableLines.length}`);
      }
    } else {
      stableLines.forEach(line => output.push(line));
    }
  }

  // Process the change region
  const changes = region.changes;
  const mineChangesInRegion = changes.filter(c => c.side === 'mine');
  const theirsChangesInRegion = changes.filter(c => c.side === 'theirs');

  if (mode === 'regions') {
    // Determine region type
    if (mineChangesInRegion.length === 0) {
      // Only theirs changed
      const theirs Replacement = theirs.slice(
        theirsChangesInRegion[0].docStart,
        theirsChangesInRegion[theirsChangesInRegion.length - 1].docEnd
      );
      output.push(`theirs ${theirsReplacement.length}`);
    } else if (theirsChangesInRegion.length === 0) {
      // Only mine changed
      const mineReplacement = mine.slice(
        mineChangesInRegion[0].docStart,
        mineChangesInRegion[mineChangesInRegion.length - 1].docEnd
      );
      output.push(`mine ${mineReplacement.length}`);
    } else {
      // Both changed, check for conflict
      const mineLinesSet = new Set(mine.slice(
        mineChangesInRegion[0].docStart,
        mineChangesInRegion[mineChangesInRegion.length - 1].docEnd
      ));
      const theirsLines = theirs.slice(
        theirsChangesInRegion[0].docStart,
        theirsChangesInRegion[theirsChangesInRegion.length - 1].docEnd
      );
      const theirsLinesSet = new Set(theirsLines);

      const mineReplacement = mine.slice(
        mineChangesInRegion[0].docStart,
        mineChangesInRegion[mineChangesInRegion.length - 1].docEnd
      );
      const baseReplacement = base.slice(region.baseStart, region.baseEnd);

      if (JSON.stringify(mineReplacement) === JSON.stringify(theirsLines)) {
        output.push(`both ${mineReplacement.length}`);
      } else {
        output.push(`conflict mine=${mineReplacement.length} base=${baseReplacement.length} theirs=${theirsLines.length}`);
        hasConflict = true;
      }
    }
  } else {
    // Merge or merge2 mode
    const baseRegion = base.slice(region.baseStart, region.baseEnd);

    if (mineChangesInRegion.length === 0) {
      // Only theirs changed
      const theirsReplacement = theirs.slice(
        theirsChangesInRegion[0].docStart,
        theirsChangesInRegion[theirsChangesInRegion.length - 1].docEnd
      );
      theirsReplacement.forEach(line => output.push(line));
    } else if (theirsChangesInRegion.length === 0) {
      // Only mine changed
      const mineReplacement = mine.slice(
        mineChangesInRegion[0].docStart,
        mineChangesInRegion[mineChangesInRegion.length - 1].docEnd
      );
      mineReplacement.forEach(line => output.push(line));
    } else {
      // Both changed
      const mineReplacement = mine.slice(
        mineChangesInRegion[0].docStart,
        mineChangesInRegion[mineChangesInRegion.length - 1].docEnd
      );
      const theirsReplacement = theirs.slice(
        theirsChangesInRegion[0].docStart,
        theirsChangesInRegion[theirsChangesInRegion.length - 1].docEnd
      );

      // Check resolution
      if (JSON.stringify(mineReplacement) === JSON.stringify(theirsReplacement)) {
        // Same change on both sides
        mineReplacement.forEach(line => output.push(line));
      } else if (JSON.stringify(mineReplacement) === JSON.stringify(baseRegion)) {
        // Mine equals base, use theirs
        theirsReplacement.forEach(line => output.push(line));
      } else if (JSON.stringify(theirsReplacement) === JSON.stringify(baseRegion)) {
        // Theirs equals base, use mine
        mineReplacement.forEach(line => output.push(line));
      } else {
        // Conflict
        output.push('<<<<<<< mine');
        mineReplacement.forEach(line => output.push(line));
        if (mode === 'merge') {
          output.push('||||||| base');
          baseRegion.forEach(line => output.push(line));
        }
        output.push('=======');
        theirsReplacement.forEach(line => output.push(line));
        output.push('>>>>>>> theirs');
        hasConflict = true;
      }
    }
  }

  basePos = region.baseEnd;
}

// Add final stable region
if (basePos < base.length) {
  const stableLines = base.slice(basePos);
  if (mode === 'regions') {
    if (stableLines.length > 0) {
      output.push(`stable ${stableLines.length}`);
    }
  } else {
    stableLines.forEach(line => output.push(line));
  }
}

// Output
if (output.length > 0) {
  process.stdout.write(output.join('\n') + '\n');
}

process.exit(hasConflict ? 1 : 0);
"}

