 * Line based three-way merge.
 *
 * Every helper here works on arrays of whole lines compared as exact strings.
 */

/**
 * Split a document into its lines: the input is cut on newlines and the empty
 * tail a trailing newline leaves is dropped.
 */
export function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

/**
 * Cut the input into the documents the `%%%` lines separate.
 */
export function splitParts(text) {
  const parts = [[]]
  for (const line of splitLines(text)) {
    if (line === '%%%') parts.push([])
    else parts[parts.length - 1].push(line)
  }
  return parts
}

/**
 * The matched pairs of a longest common subsequence of `doc` and `base`,
 * choosing the matches that come earliest.
 */
export function lcsMatches(doc, base) {
  const n = doc.length
  const m = base.length
  // lengths[i][j] is the length of the longest common subsequence of the
  // suffixes doc[i..] and base[j..].
  const lengths = []
  for (let i = 0; i <= n; i++) lengths.push(new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      lengths[i][j] = doc[i] === base[j]
        ? lengths[i + 1][j + 1] + 1
        : Math.max(lengths[i + 1][j], lengths[i][j + 1])
    }
  }
  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (doc[i] === base[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (lengths[i][j + 1] >= lengths[i + 1][j]) {
      // Advancing the base keeps a subsequence at least as long, and the base
      // wins the tie.
      j++
    } else {
      i++
    }
  }
  return matches
}

/**
 * The changes of `doc` against `base`: runs of base lines replaced by runs of
 * document lines.
 */
export function changesOf(doc, base) {
  const changes = []
  let baseAt = 0
  let docAt = 0
  const add = (baseEnd, docEnd) => {
    if (baseEnd > baseAt || docEnd > docAt) {
      changes.push({ baseStart: baseAt, baseEnd, docStart: docAt, docEnd })
    }
  }
  for (const [docIdx, baseIdx] of lcsMatches(doc, base)) {
    add(baseIdx, docIdx)
    baseAt = baseIdx + 1
    docAt = docIdx + 1
  }
  add(base.length, doc.length)
  return changes
}

/**
 * The regions of the merge, in base order: stable stretches the merge keeps and
 * changed stretches one or both sides touched.
 */
export function regionsOf(mine, base, theirs) {
  const changes = []
  for (const change of changesOf(mine, base)) changes.push({ ...change, side: 'mine' })
  for (const change of changesOf(theirs, base)) changes.push({ ...change, side: 'theirs' })
  changes.sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return a.baseEnd - b.baseEnd
    return a.side === 'mine' ? -1 : 1
  })

  const groups = []
  for (const change of changes) {
    const last = groups[groups.length - 1]
    if (last && change.baseStart <= last.baseEnd) {
      last.baseEnd = Math.max(last.baseEnd, change.baseEnd)
      last.changes.push(change)
    } else {
      groups.push({ baseStart: change.baseStart, baseEnd: change.baseEnd, changes: [change] })
    }
  }

  const regions = []
  let baseAt = 0
  for (const group of groups) {
    if (group.baseStart > baseAt) {
      regions.push({ kind: 'stable', lines: base.slice(baseAt, group.baseStart) })
    }
    const baseLines = base.slice(group.baseStart, group.baseEnd)
    const mineLines = sideLines(mine, baseLines, group, 'mine')
    const theirsLines = sideLines(theirs, baseLines, group, 'theirs')
    regions.push({ kind: 'changed', mine: mineLines, base: baseLines, theirs: theirsLines })
    baseAt = group.baseEnd
  }
  if (baseAt < base.length) regions.push({ kind: 'stable', lines: base.slice(baseAt) })
  return regions
}

/** The lines one side puts in place of the base lines of a region. */
function sideLines(doc, baseLines, group, side) {
  const own = group.changes.filter(change => change.side === side)
  if (own.length === 0) return baseLines.slice()
  let docStart = Infinity
  let docEnd = -Infinity
  let baseStart = Infinity
  let baseEnd = -Infinity
  for (const change of own) {
    docStart = Math.min(docStart, change.docStart)
    docEnd = Math.max(docEnd, change.docEnd)
    baseStart = Math.min(baseStart, change.baseStart)
    baseEnd = Math.max(baseEnd, change.baseEnd)
  }
  const before = baseStart - group.baseStart
  const after = group.baseEnd - baseEnd
  return doc.slice(docStart - before, docEnd + after)
}

export function sameLines(a, b) {
  return a.length === b.length && a.every((line, index) => line === b[index])
}

/**
 * How a changed region resolves: `both`, `mine`, `theirs` or `conflict`.
 */
export function resolve(region) {
  if (sameLines(region.mine, region.theirs)) return 'both'
  if (sameLines(region.mine, region.base)) return 'theirs'
  if (sameLines(region.theirs, region.base)) return 'mine'
  return 'conflict'
}
