 * Line based three-way merge.
 *
 * Every helper here works on arrays of whole lines compared as exact strings.
 */

/**
 * Split a document into its lines: the input is cut on newlines and the empty
 * tail a trailing newline leaves is dropped.
 */
export function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

/**
 * Cut the input into the documents the `%%%` lines separate.
 */
export function splitParts(text) {
  const parts = [[]]
  for (const line of splitLines(text)) {
    if (line === '%%%') parts.push([])
    else parts[parts.length - 1].push(line)
  }
  return parts
}

/**
 * The matched pairs of a longest common subsequence of `doc` and `base`,
 * choosing the matches that come earliest.
 */
export function lcsMatches(doc, base) {
  const n = doc.length
  const m = base.length
  // lengths[i][j] is the length of the longest common subsequence of the
  // suffixes doc[i..] and base[j..].
  const lengths = []
  for (let i = 0; i <= n; i++) lengths.push(new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      lengths[i][j] = doc[i] === base[j]
        ? lengths[i + 1][j + 1] + 1
        : Math.max(lengths[i + 1][j], lengths[i][j + 1])
    }
  }
  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (doc[i] === base[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (lengths[i][j + 1] >= lengths[i + 1][j]) {
      // Advancing the base keeps a subsequence at least as long, and the base
      // wins the tie.
      j++
    } else {
      i++
    }
  }
  return matches
}

