{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { readFileSync } from 'node:fs'
import { splitParts, regionsOf, resolve } from './diff3.js'

const MODES = ['merge', 'merge2', 'regions']

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

const mode = process.argv[2]
if (process.argv.length !== 3 || !MODES.includes(mode)) {
  fail('usage: cli.js merge|merge2|regions')
}

let input = ''
try {
  input = readFileSync(0, 'utf8')
} catch {
  input = ''
}

const parts = splitParts(input)
if (parts.length !== 3) fail('expected three parts separated by %%%')

const [mine, base, theirs] = parts
const regions = regionsOf(mine, base, theirs)

const out = []
let conflicted = false

for (const region of regions) {
  if (region.kind === 'stable') {
    if (mode === 'regions') out.push(`stable ${region.lines.length}`)
    else out.push(...region.lines)
    continue
  }
  const how = resolve(region)
  if (how === 'conflict') conflicted = true
  if (mode === 'regions') {
    if (how === 'conflict') {
      out.push(`conflict mine=${region.mine.length} base=${region.base.length} theirs=${region.theirs.length}`)
    } else if (how === 'both') {
      out.push(`both ${region.mine.length}`)
    } else {
      out.push(`${how} ${region[how].length}`)
    }
    continue
  }
  if (how === 'both' || how === 'mine') {
    out.push(...region.mine)
  } else if (how === 'theirs') {
    out.push(...region.theirs)
  } else {
    out.push('<<<<<<< mine', ...region.mine)
    if (mode === 'merge') out.push('||||||| base', ...region.base)
    out.push('=======', ...region.theirs, '>>>>>>> theirs')
  }
}

if (out.length > 0) process.stdout.write(out.map(line => `${line}\n`).join(''))
process.exit(conflicted ? 1 : 0)
"}

